import sys
from collections import defaultdict, deque

MOD = 10**9 + 7

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def euler_totient(n):
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def bfs(graph, start):
    n = len(graph)
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    queue = deque([start])
    while queue:
        u = queue.popleft()
        for v in graph[u]:
            if dist[v] == float('inf'):
                dist[v] = dist[u] + 1
                queue.append(v)
    return dist

def main():
    input = sys.stdin.readline
    n = int(input())
    a = list(map(int, input().split()))
    graph = defaultdict(list)
    for _ in range(n - 1):
        u, v = map(int, input().split())
        graph[u].append(v)
        graph[v].append(u)

    expected_value = 0
    total_pairs = n * (n - 1)

    for u in range(1, n + 1):
        dist_u = bfs(graph, u)
        for v in range(1, n + 1):
            if u != v:
                phi_product = euler_totient(a[u - 1] * a[v - 1])
                distance = dist_u[v]
                expected_value += phi_product * distance
                expected_value %= MOD

    inverse_total_pairs = pow(total_pairs, MOD - 2, MOD)
    result = (expected_value * inverse_total_pairs - 1) % MOD
    print(result)

if __name__ == "__main__":
    main()
